import 'package:flutter/material.dart';

// 应用入口：runApp 把根 Widget 挂载到屏幕上
void main() => runApp(const MyApp());

/// 无状态组件：只负责搭建 MaterialApp 外壳，自身没有可变数据
class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'setState Demo',
      theme: ThemeData(primarySwatch: Colors.blue),
      home: const CounterPage(),
    );
  }
}

/// 有状态组件：本身不可变，状态保存在它创建的 State 对象里
class CounterPage extends StatefulWidget {
  const CounterPage({super.key});

  @override
  State<CounterPage> createState() => _CounterPageState();
}

/// 与 CounterPage 配对的 State 类，用 _ 前缀保持私有
class _CounterPageState extends State<CounterPage> {
  // 可变状态：注意这里不能加 final
  int _count = 0;

  // 事件处理函数：在 setState 回调中修改状态，触发界面重建
  void _increment() {
    setState(() {
      _count++; // 只在回调里改数据
    });
  }

  @override
  Widget build(BuildContext context) {
    // 每次 setState 后，Flutter 会重新调用这个 build 方法
    return Scaffold(
      appBar: AppBar(title: const Text('setState 入门')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 字符串插值读取最新状态
            Text('当前计数：$_count', style: const TextStyle(fontSize: 28)),
            const SizedBox(height: 16),
            ElevatedButton(
              onPressed: _increment, // 点击时调用，触发重建
              child: const Text('加 1'),
            ),
          ],
        ),
      ),
    );
  }
}

